  " · NEW": " · NUEVO",
  " completed.": " completado.",
  " unread support tickets": " tickets de soporte no leídos",
  ". Wallet overflow is saved here.": ". El desbordamiento de la billetera se guarda aquí.",
  "· {v1} · {v2} · revision {v3}": "· {v1} · {v2} · revisión {v3}",
